SOURCE_INPUTS={'sink': {'asset_id': 'laboratory-open-frame-sink-table-01', 'sha256': 'ee89e4a1ff1991d65061845498c56d4855fb851f17c630bbb757b9edc11dae1b', 'compressed': ''}, 'cabinet': {'asset_id': 'interior-pantry-cabinet-01', 'sha256': '5ef6434fb3f2060318828038e743f8212a8f5fedc6b4b7486e65f1dd802c82c7', 'compressed': ''}}
